with
tl(t) as (values ('billing_audit_log'),('billing_company'),('billing_features'),('billing_invoice_counters'),('billing_lifecycle_settings'),('billing_live_tenants'),('billing_notices'),('billing_owner_action_keys'),('billing_package_version_approvals'),('billing_package_version_features'),('billing_package_versions'),('billing_packages'),('billing_rate_card'),('billing_receipt_counters'),('invoice_lines'),('invoice_pay_tokens'),('invoice_receipts'),('invoices'),('ops_audit_log'),('payment_attempts'),('payment_events'),('payments'),('sms_counter_reconciliations'),('subscription_events'),('tenant_credits'),('tenant_minute_grants'),('tenant_subscriptions'),('voice_wallet_alert_state'),('wallet_ledger')),
T as (select c.oid, c.relname from pg_class c join tl on tl.t=c.relname where c.relnamespace='public'::regnamespace and c.relkind='r'),
V as (select c.oid, c.relname from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v' and c.relname in ('billing_notice_outbox','billing_subscription_read','notify_sms_billable','tenant_billing_state','tenant_credit_balance')),
F as (select p.oid, p.proname from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f'
  and (p.proname ~ '(bill|wallet|grant_tenant|waive|package|overage|charge|invoice|payment|period|minute|ledger|credit|on_demand|subscri|sms_counter|spend|receipt|prorat|checkout|pay_token|collection)' or p.proname='tenants_a_new_signup_trial')
  and p.proname not in ('parse_payments_text','payments_to_v2','payments_valid','admin_set_business_suspended')),
TG as (select t.oid, t.tgname, t.tgrelid, c.relname, t.tgenabled from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace='public'::regnamespace and (t.tgrelid in (select oid from T) or (c.relname='tenants' and t.tgfoid in (select oid from F)))),
CJ as (select jobname, schedule, command, active from cron.job where jobname in ('scalers-package-period-rollover','sms-counter-drift-daily'))
